:root{
  --mobile-header-offset: 140px; /* increase if the button is still under the header */
  --mobile-side-gap: 16px;
}

/* reviews section full width */
#zfouec .block-layout,
#zfouec .block-layout--layout{
  max-width: none !important;
  padding: 0 !important;
}
#zfouec div:nth-of-type(2){
  max-width: none !important;
  padding-inline: 0 !important;
}

/* mobile sticky emergency button */
@media (max-width: 920px){
  #zyz1gb .emergency-embed{
    position: fixed !important;
    left: var(--mobile-side-gap) !important;
    right: var(--mobile-side-gap) !important;
    top: var(--mobile-header-offset) !important; /* keeps it below the header */
    bottom: auto !important;
    z-index: 2147483647 !important;

    display: flex !important;
    justify-content: center !important;
    margin: 0 !important;
    transform: none !important;
  }

  #zyz1gb .emergency-embed &gt; a.floating-emergency-call{
    all: unset !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    text-align: center !important;

    width: 100% !important;
    max-width: 420px !important;

    background: #e11d2e !important;
    color: #fff !important;
    padding: 12px 14px !important;
    border-radius: 14px !important;
    font-weight: 900 !important;
    line-height: 1 !important;
    cursor: pointer !important;
  }

  #zyz1gb .emergency-embed &gt; a.floating-emergency-call *{
    all: unset !important;
    color: #fff !important;
  }
}
/* reviews widget inner wrapper is still capped — force it full width */
#zfouec [style*=\&quot;grid-template-columns\&quot;]{
  max-width: none !important;
  width: 100% !important;
}
#zfouec [style*=\&quot;grid-template-columns\&quot;] &gt; *{
  max-width: none !important;
}
@media (max-width: 920px){
  /* target the actual button element inside the zyz1gb section */
  #zyz1gb a.floating-emergency-call{
    position: fixed !important;
    left: 16px !important;
    right: 16px !important;
    top: 140px !important;      /* increase if needed */
    z-index: 2147483647 !important;
  }
}
/* ===== reviews section: full width (block id zynuu-) ===== */
section[data-block-id=\&quot;zynuu-\&quot;] .block-layout-container,
section[data-block-id=\&quot;zynuu-\&quot;] .block-layout[data-block-ref=\&quot;zynuu-\&quot;]{
  max-width: none !important;
  width: 100% !important;
}

/* the builder limits desktop width via this css variable (yours is 1224px) */
@media (min-width: 920px){
  section[data-block-id=\&quot;zynuu-\&quot;] .block-layout[data-block-ref=\&quot;zynuu-\&quot;]{
    --grid-template-columns: 100% !important;
  }
}

/* ===== emergency button: keep it below the sticky header (mobile) ===== */
@media (max-width: 920px){
  section[data-block-id=\&quot;zyz1gb\&quot;] a.floating-emergency-call{
    position: fixed !important;
    left: 16px !important;
    right: 16px !important;
    top: 140px !important;     /* raise/lower this as needed */
    z-index: 2147483647 !important;
  }
}
/* reviews widget: remove inner boxing/padding so it can expand */
section[data-block-id=\&quot;zynuu-\&quot;] .es-widget-background-wrapper{
  padding-left: 0 !important;
  padding-right: 0 !important;
  max-width: none !important;
  width: 100% !important;
}
section[data-block-id=\&quot;zynuu-\&quot;] .es-main-container,
section[data-block-id=\&quot;zynuu-\&quot;] .es-widget-background-container,
section[data-block-id=\&quot;zynuu-\&quot;] .es-embed-root{
  max-width: none !important;
  width: 100% !important;
}
//* ===== simple hostinger back to top button ===== */
a[href=\&quot;#top\&quot;]{
  position: fixed !important;
  right: 20px !important;
  bottom: 20px !important;
  width: 56px !important;
  height: 56px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: #1f7a3a !important;
  color: #ffffff !important;
  font-size: 28px !important;
  font-weight: 900 !important;
  line-height: 1 !important;
  text-decoration: none !important;
  border-radius: 14px !important;
  box-shadow: 0 6px 15px rgba(0,0,0,0.25) !important;
  cursor: pointer !important;
  z-index: 2147483646 !important;
  animation: bacpulse 2s infinite !important;
}

a[href=\&quot;#top\&quot;]:hover{
  transform: translatey(-4px) scale(1.05) !important;
  background: #166534 !important;
  color: #ffffff !important;
}

@keyframes bacpulse{
  0%{
    box-shadow: 0 0 0 0 rgba(31,122,58,0.55), 0 6px 15px rgba(0,0,0,0.25);
  }
  70%{
    box-shadow: 0 0 0 14px rgba(31,122,58,0), 0 6px 15px rgba(0,0,0,0.25);
  }
  100%{
    box-shadow: 0 0 0 0 rgba(31,122,58,0), 0 6px 15px rgba(0,0,0,0.25);
  }
}

html{
  scroll-behavior: smooth;
}

@media (max-width: 920px){
  a[href=\&quot;#top\&quot;]{
    right: 16px !important;
    bottom: 90px !important;
    width: 54px !important;
    height: 54px !important;
    font-size: 24px !important;
  }
}
